<?php
require_once __DIR__ . '/layout.php';
require_once __DIR__.'/finance.php';
$user = require_roles();
$error = null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    require_roles(['admin','manager']); check_csrf();
    try {
        if (($_POST['action'] ?? '')!=='delete_client') { throw new InvalidArgumentException('Invalid action.'); }
        $id=positive_id($_POST['id'] ?? null);
        query('UPDATE clients SET deleted_at=NOW(),is_active=0 WHERE id=? AND deleted_at IS NULL',[$id]);
        flash('Client deleted.'); redirect('add-client.php');
    } catch (Throwable $e) { $error=mutation_error($e); }
}
$clients=clients(); $brandAssets=rows('SELECT a.*,c.client_name FROM brand_assets a JOIN clients c ON c.id=a.client_id WHERE c.deleted_at IS NULL AND c.is_active=1 ORDER BY c.client_name,a.asset_type,a.title'); page_start('Clients','add-client.php'); error_message($error);
?><div class="toolbar"><p class="muted">Client details are shared with your team.</p><?php if (is_staff()): ?><a class="button" href="admin-add-client.php">+ Add client</a><?php endif; ?></div><section class="panel"><div class="client-search"><input type="search" id="clientSearch" placeholder="Search clients by name, website, status or package..." aria-label="Search clients" autocomplete="off"><span class="muted" id="clientSearchCount"></span></div><div class="table-scroll client-table-scroll"><table id="clientTable"><thead><tr><th>Logo</th><th>Client name</th><th>Status</th><th>Website</th><?php if (is_staff()): ?><th>Remaining</th><th>Package</th><th>Total payment</th><th>Paid</th><?php endif; ?><th>Actions</th></tr></thead><tbody><?php if (!$clients) empty_row(is_staff()?9:5); foreach ($clients as $client): ?><tr><td><?php if ($client['logo_path']): ?><img class="client-logo" src="client-logo.php?id=<?= (int)$client['id'] ?>" alt="<?= h($client['client_name']) ?> logo"><?php else: ?>—<?php endif; ?></td><td><?= h($client['client_name']) ?></td><td><?php [$clStatusKey,$clStatusLabel]=client_status_info($client); ?><span class="badge client-status is-<?= h($clStatusKey) ?>"><?= h($clStatusLabel) ?></span></td><td><?php if ($client['website_url']): ?><a href="<?= h($client['website_url']) ?>" target="_blank" rel="noopener noreferrer"><?= h($client['website_url']) ?></a><?php else: ?>—<?php endif; ?></td><?php if (is_staff()): ?><td><?= h(money_label($client['remaining_amount'])) ?></td><td><?= h($client['package']) ?></td><td><?= h(money_label($client['payment_total'])) ?></td><td><?= h(money_label($client['paid_amount'])) ?></td><?php endif; ?><td><div class="actions"><a class="button secondary" href="client-profile.php?id=<?= (int)$client['id'] ?>">Profile</a><?php detail_button('client-'.$client['id']); if (is_staff()): ?><a class="icon-button" href="admin-add-client.php?id=<?= $client['id'] ?>" title="Edit client" aria-label="Edit client"><?= icon('edit') ?></a><?php delete_button((int)$client['id'],'delete_client','Delete this client?'); endif; ?></div></td></tr><?php endforeach; ?><tr class="client-no-match" hidden><td colspan="<?= is_staff()?9:5 ?>" class="empty">No clients match your search.</td></tr></tbody></table></div></section><script>(function(){var i=document.getElementById('clientSearch'),t=document.getElementById('clientTable'),c=document.getElementById('clientSearchCount');if(!i||!t)return;var none=t.querySelector('.client-no-match'),rows=[].slice.call(t.tBodies[0].rows).filter(function(r){return r!==none&&!r.querySelector('td.empty')});function run(){var q=i.value.trim().toLowerCase(),n=0;rows.forEach(function(r){var m=!q||r.textContent.toLowerCase().indexOf(q)>-1;r.hidden=!m;if(m)n++;});none.hidden=n>0||!rows.length;c.textContent=q?n+' of '+rows.length+' clients':'';}i.addEventListener('input',run);})();</script><?php foreach ($clients as $client) {
    $fields=['Client name'=>$client['client_name'],'Client type'=>ucfirst($client['client_type']),'Status'=>client_status_info($client)[1],'Project age'=>project_age($client['starting_date']),'Phone'=>$client['phone'],'Starting date'=>$client['starting_date'],'Ending date'=>$client['ending_date'],'Website'=>$client['website_url'],'Domain name'=>$client['domain_name']??'','Domain provider'=>$client['domain_provider']??'','Domain username'=>$client['domain_username']??'','Domain password'=>is_staff()?(credential_decrypt($client['domain_password_cipher']??null)?:'Not set'):'','Domain expiry'=>$client['domain_expiry']??'','Google Business Profile URL'=>$client['gmb_url'],'GMB username'=>$client['gmb_username']??'','GMB password'=>is_staff()?(credential_decrypt($client['gmb_password_cipher']??null)?:'Not set'):'','GMB access granted'=>!empty($client['gmb_access_granted'])?'Yes':'No','Monthly reels'=>(string)$client['monthly_reels'],'Monthly posters'=>(string)$client['monthly_posters'],'Monthly carousels'=>(string)$client['monthly_carousels'],'Monthly blogs'=>(string)$client['monthly_blogs'],'Monthly work remark'=>$client['monthly_work_remark']];
    $socialLinks=rows('SELECT platform_name,url,username,password_cipher FROM client_social_links WHERE client_id=? ORDER BY id',[$client['id']]);
    foreach ($socialLinks as $index=>$link) $fields['Social · '.$link['platform_name'].' #'.($index+1)]=$link['url'];
    if (is_staff()) foreach ($socialLinks as $index=>$link) {
        $prefix=$link['platform_name'].' #'.($index+1);
        $fields[$prefix.' username']=$link['username']?:'Not set';
        $fields[$prefix.' password']=credential_decrypt($link['password_cipher'])?:'Not set';
    }
    if (!$socialLinks && $client['social_media_url']) $fields['Social media']=$client['social_media_url'];
    if (is_staff()) {
        $login=$client['user_id']?one('SELECT username,credential_cipher FROM users WHERE id=?',[$client['user_id']]):null;
        $fields['Client login username']=$login['username']??'Login not created. Use Edit client to create credentials.';
        if ($user['role']==='admin') $fields['Client login password']=$login?(credential_decrypt($login['credential_cipher'])?:'Not recoverable. Set a new password in Edit client.'):'Not set';
        $fields['Remaining']=money_label($client['remaining_amount']);
        $fields['Package']=$client['package']; $fields['Total payment']=money_label($client['payment_total']); $fields['Paid']=money_label($client['paid_amount']);
        foreach (rows('SELECT * FROM client_payments WHERE client_id=? ORDER BY payment_date,id',[$client['id']]) as $payment) $fields['Payment #'.$payment['id'].' · '.$payment['payment_date']]=money_label($payment['amount']);
    }
    detail_dialog('client-'.$client['id'],$client['client_name'],$fields);
} ?><section class="panel" id="brand-assets"><div class="panel-heading"><h2>Client brand assets</h2><span class="badge"><?= count($brandAssets) ?> files</span></div><p class="muted">Client logos and saved brand files are collected here.</p><div class="table-scroll"><table><thead><tr><th>Client</th><th>Asset type</th><th>File</th><th>Download</th></tr></thead><tbody><?php if (!$brandAssets) empty_row(4,'No brand files have been saved.'); foreach ($brandAssets as $asset): ?><tr><td><?= h($asset['client_name']) ?></td><td><?= h($asset['asset_type']) ?></td><td><?= h($asset['title']) ?></td><td><a href="download-asset.php?id=<?= (int)$asset['id'] ?>" class="icon-button" aria-label="Download file" title="Download file"><?= icon('download') ?></a></td></tr><?php endforeach; ?></tbody></table></div><h3>Client logos</h3><div class="brand-logo-grid"><?php foreach ($clients as $client): ?><article><?php if ($client['logo_path']): ?><img src="client-logo.php?id=<?= (int)$client['id'] ?>" alt="<?= h($client['client_name']) ?> logo"><?php else: ?><span class="muted">No logo</span><?php endif; ?><strong><?= h($client['client_name']) ?></strong><span><?= h($client['website_url']?:'') ?></span></article><?php endforeach; ?></div></section><?php page_end(); ?>
